python3 -c "
import yaml, glob
for f in sorted(glob.glob('.github/workflows/*.yml')):
    try:
        d = yaml.safe_load(open(f))
        jobs = d.get('jobs', {})
        names = set(jobs.keys())
        # check needs references exist
        for jid, j in jobs.items():
            for n in (j.get('needs') or []):
                base = n.split('.')[0]
                if base not in names:
                    print(f'{f}: job {jid} needs unknown job {n}')
    except Exception as e:
        print(f'{f}: PARSE ERROR {e}')
print('yaml+needs validation done')
"

