arguments.command:
python3 -c "
import yaml, glob
bad = 0
for f in sorted(glob.glob('.github/workflows/*.yml')):
    d = yaml.safe_load(open(f))
    jobs = d.get('jobs', {})
    names = set(jobs.keys())
    for jid, j in jobs.items():
        needs = j.get('needs') or []
        if isinstance(needs, str): needs = [needs]
        for n in needs:
            base = str(n).split('.')[0]
            if base not in names:
                print(f'{f}: job {jid} NEEDS UNKNOWN {n}'); bad += 1
        u = j.get('uses')
        if u and u.startswith('./'):
            path = u[2:].split('@')[0]
            import os
            if not os.path.exists(path):
                print(f'{f}: job {jid} USES MISSING {u}'); bad += 1
        for sid, s in (j.get('steps') or {}).items() if isinstance(j.get('steps'), list) else []:
