for wf in ['browser-ext','office-addin','build-macos','bench','bench-4.0','coverage-gardener','daily-publish','pages','publish-fa-llm','release-appstore','shard-rebalance','site-mobile','store-metadata','build-mobile','machine-merge','merge-trigger']:
